 "content": "def transform(grid):
    """Recolor each 4-connected component of zeros with size > 1 as 8."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            component = [(r, c)]
            seen.add((r, c))
            for x, y in component:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        component.append((nx, ny))
            if len(component) > 1:
                for x, y in component:
                    out[x][y] = 8
    return out
